contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint a1, uint a2) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= a1 && address(c).balance - a1 >= a2);
        require(address(this).balance + a1 + a2 > address(this).balance);
        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;
        c.sendTo(address(this), a1); if (__ESBMC_reverted()) return;
        c.sendTo(address(this), a2); if (__ESBMC_reverted()) return;
        assert(address(c).balance + a1 + a2 == balCBefore && address(this).balance == balTestBefore + a1 + a2);
    }

    receive() external payable {}
}

