// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 a1, uint256 a2) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(c).balance >= a1 && address(c).balance - a1 >= a2);
        vm.assume(address(this).balance + a1 + a2 > address(this).balance);
        uint balCBefore = address(c).balance;
        uint balTestBefore = address(this).balance;
        try c.sendTo(address(this), a1) {} catch { return; }
        try c.sendTo(address(this), a2) {} catch { return; }
        assertTrue(address(c).balance + a1 + a2 == balCBefore && address(this).balance == balTestBefore + a1 + a2);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
